import { parseSessionCookie } from "./cookies.ts";
import { fetchBackupRecord } from "./db.ts";

Deno.serve({ port: 8000 }, async (req: Request) => {
  const url = new URL(req.url);
  if (req.method === "GET" && url.pathname.startsWith("/backups/")) {
    const backupId = url.pathname.split("/")[2];
    const session = await parseSessionCookie(req.headers.get("Cookie"));
    if (!session || !session.userId) {
      return new Response("Unauthorized", { status: 401 });
    }

    // Scopes the query to ensure backup belongs to authenticated session's tenant
    const backup = await fetchBackupRecord(backupId);
    if (!backup || backup.tenantId !== session.tenantId) {
      return new Response("Backup not found or access denied", { status: 403 });
    }

    const fileData = await Deno.readFile(backup.storagePath);
    return new Response(fileData, {
      headers: {
        "Content-Type": "application/octet-stream",
        "Content-Disposition": `attachment; filename="${backup.fileName}"`
      }
    });
  }
  return new Response("Not Found", { status: 404 });
});
